        let db = cx.db;
        fn node<N: AstNode>(it: Option<InFile<N>>) -> Option<InFile<SyntaxNode>> {
            it.map(|it| it.map(syntax_of))
        }
        match self {
            Def::Field(it) => it.source(db).map(|it| {
                it.map(|it| match it {
                    hir::FieldSource::Named(it) => syntax_of(it),
                    hir::FieldSource::Pos(it) => syntax_of(it),
