fn parent<'db>(
    cx: &Cx<'_, 'db>,
    node: InFile<Node<'db>>,
    stop: impl Fn(Node<'db>) -> bool,
) -> Option<InFile<Node<'db>>> {
    let (mut file, mut at) = (node.file_id, node.value.parent());
    loop {
        while let Some(node) = at {
            if stop(node) {
                return Some(InFile::new(file, node));
            }
            at = node.parent();
